import sys, itertools, subprocess, random

HEX="0123456789abcdefABCDEF"
def is_cap_letter(c): return c.isascii() and (c.isalnum() or c=='_') and (c.isdigit() or c.isalpha() or c=='_')
def is_cap_letter(c):
    o=ord(c)
    return (48<=o<=57) or (65<=o<=90) or (97<=o<=122) or o==95
def is_digit(c): return '0'<=c<='9'
def is_alpha_us(c):
    o=ord(c); return (65<=o<=90) or (97<=o<=122) or o==95

def check_ambiguous(rep):
    i=0; n=len(rep)
    while i<n:
        if rep[i]!='$': i+=1; continue
        if i+1<n and rep[i+1]=='$': i+=2; continue
        if i+1<n and rep[i+1]=='{':
            j=rep.find('}', i+2)
            if j!=-1: i=j+1
            else: i+=1
            continue
        j=i+1
        while j<n and is_digit(rep[j]): j+=1
        if j>i+1:
            k=j
            while k<n and is_alpha_us(rep[k]): k+=1
            if k>j: return (rep[i+1:j], rep[j:k], i+1, k-(i+1))
            i=j
        else: i+=1
    return None

CTRLPIC={'\t':'␉','\n':'␊','\r':'␍'}
def render(rep): return ''.join(CTRLPIC.get(c,c) for c in rep)

def amb_msg(rep):
    r=check_ambiguous(rep)
    if r is None: return None
    num,suf,start,ln=r
    return ("error: The numbered capture group `$%s` in the replacement text is ambiguous.\n"
            "hint: Use curly braces to disambiguate it `${%s}%s`.\n"
            "%s\n%s%s\n" % (num,num,suf,render(rep),' '*start,'^'*ln))

def unescape(s):
    out=[]; i=0; n=len(s)
    while i<n:
        c=s[i]
        if c=='\\' and i+1<n:
            d=s[i+1]
            if d=='n': out.append('\n'); i+=2; continue
            if d=='t': out.append('\t'); i+=2; continue
            if d=='r': out.append('\r'); i+=2; continue
            if d=='\\': out.append('\\'); i+=2; continue
            if d=='x':
                h=s[i+2:i+4]
                if len(h)==2 and all(ch in HEX for ch in h):
                    out.append(chr(int(h,16))); i+=5; continue
                out.append('\\'); out.append('x'); i+=2; continue
            out.append('\\'); i+=1; continue
        out.append(c); i+=1
    return ''.join(out)

def parse_u32(s):
    if not s: return None
    t=s[1:] if s[0]=='+' else s
    if not t or not all('0'<=c<='9' for c in t): return None
    v=int(t)
    return v if v<=0xffffffff else None

def find_cap_ref(rep):
    if len(rep)<=1 or rep[0]!='$': return None
    i=1
    if rep[i]=='{':
        start=i+1; j=start
        while j<len(rep) and rep[j]!='}': j+=1
        if j>=len(rep): return None
        return (rep[start:j], j+1)
    e=i
    while e<len(rep) and is_cap_letter(rep[e]): e+=1
    if e==i: return None
    return (rep[i:e], e)

def expand(tpl, bynum, byname):
    out=[]; rep=tpl
    while rep:
        idx=rep.find('$')
        if idx<0: out.append(rep); break
        out.append(rep[:idx]); rep=rep[idx:]
        if len(rep)>1 and rep[1]=='$':
            out.append('$'); rep=rep[2:]; continue
        r=find_cap_ref(rep)
        if r is None:
            out.append('$'); rep=rep[1:]; continue
        cap,end=r; rep=rep[end:]
        num=parse_u32(cap)
        if num is not None: out.append(bynum.get(num,''))
        else: out.append(byname.get(cap,''))
    return ''.join(out)

def model(rep, bynum, byname, prefix, suffix):
    m=amb_msg(rep)
    if m is not None: return (1,'',m)
    tpl=unescape(rep)
    return (0, prefix+expand(tpl,bynum,byname)+suffix, '')
